/*
 * filter -- a shellcode runner guarded by a tiny transformer.
 *
 * We read your shellcode, run it through a small byte-level transformer that
 * was trained to recognise "malicious" code, and only execute it if the model
 * decides it is benign. Surely a neural network cannot be fooled.
 *
 * The model weights live in model.h (generated by gen_model.py).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <math.h>
#include <sys/mman.h>

#include "model.h"

#define MAX_LEN 0x1000

/* ------------------------------------------------------------------ */
/* the guard transformer: embedding -> causal windowed self-attention */
/* -> relu feed-forward -> max-pool over positions.                   */
/* ------------------------------------------------------------------ */

float guard_score(const unsigned char *toks, int n)
{
    if (n <= 0)
        return GUARD_B2;

    float best = -1e30f;

    for (int i = 0; i < n; i++) {
        int lo = i - GUARD_W;
        if (lo < 0)
            lo = 0;

        /* embedding + projections for the current query */
        float xi[GUARD_D];
        for (int d = 0; d < GUARD_D; d++)
            xi[d] = GUARD_E[toks[i]][d];

        float q[GUARD_D];
        for (int a = 0; a < GUARD_D; a++) {
            float acc = 0.0f;
            for (int b = 0; b < GUARD_D; b++)
                acc += GUARD_WQ[a][b] * xi[b];
            q[a] = acc;
        }

        /* attention scores over the causal window [lo, i] */
        int win = i - lo + 1;
        float scores[GUARD_W + 1];
        float maxs = -1e30f;
        for (int t = 0; t < win; t++) {
            int j = lo + t;
            float xj[GUARD_D];
            for (int d = 0; d < GUARD_D; d++)
                xj[d] = GUARD_E[toks[j]][d];

            float k[GUARD_D];
            for (int a = 0; a < GUARD_D; a++) {
                float acc = 0.0f;
                for (int b = 0; b < GUARD_D; b++)
                    acc += GUARD_WK[a][b] * xj[b];
                k[a] = acc;
            }

            float dot = 0.0f;
            for (int d = 0; d < GUARD_D; d++)
                dot += q[d] * k[d];

            float s = GUARD_SCALE * dot + GUARD_RELBIAS[i - j];
            scores[t] = s;
            if (s > maxs)
                maxs = s;
        }

        /* softmax */
        float denom = 0.0f;
        for (int t = 0; t < win; t++) {
            scores[t] = expf(scores[t] - maxs);
            denom += scores[t];
        }

        /* context = sum_j a[j] * (Wv x[j]) */
        float ctx[GUARD_D];
        for (int d = 0; d < GUARD_D; d++)
            ctx[d] = 0.0f;
        for (int t = 0; t < win; t++) {
            int j = lo + t;
            float a = scores[t] / denom;
            float xj[GUARD_D];
            for (int d = 0; d < GUARD_D; d++)
                xj[d] = GUARD_E[toks[j]][d];
            for (int o = 0; o < GUARD_D; o++) {
                float acc = 0.0f;
                for (int b = 0; b < GUARD_D; b++)
                    acc += GUARD_WV[o][b] * xj[b];
                ctx[o] += a * acc;
            }
        }

        /* z = concat(x[i], ctx) ; h = relu(W1 z + b1) ; logit = w2.h + b2 */
        float z[2 * GUARD_D];
        for (int d = 0; d < GUARD_D; d++) {
            z[d] = xi[d];
            z[GUARD_D + d] = ctx[d];
        }

        float logit = GUARD_B2;
        for (int hh = 0; hh < GUARD_H; hh++) {
            float acc = GUARD_B1[hh];
            for (int d = 0; d < 2 * GUARD_D; d++)
                acc += GUARD_W1[hh][d] * z[d];
            if (acc < 0.0f)
                acc = 0.0f;
            logit += GUARD_W2[hh] * acc;
        }

        if (logit > best)
            best = logit;
    }

    return best;
}

/* ------------------------------------------------------------------ */

static ssize_t read_n(int fd, void *buf, size_t n)
{
    size_t got = 0;
    char *p = buf;
    while (got < n) {
        ssize_t r = read(fd, p + got, n - got);
        if (r < 0)
            return -1;
        if (r == 0)
            break;
        got += (size_t)r;
    }
    return (ssize_t)got;
}

#ifndef GUARD_NO_MAIN
int main(void)
{
    setvbuf(stdout, NULL, _IONBF, 0);
    setvbuf(stderr, NULL, _IONBF, 0);

    puts("=== filter: neural shellcode firewall ===");
    puts("Optimus Prime reporting for duty.");
    puts("Our transformer has read every exploit on the internet.");
    puts("It will happily run code it believes is harmless.");
    printf("Send your shellcode as: [4-byte little-endian length][bytes], max %d.\n",
           MAX_LEN);
    fflush(stdout);

    unsigned int len = 0;
    if (read_n(0, &len, 4) != 4) {
        puts("[!] could not read length");
        return 1;
    }
    if (len == 0 || len > MAX_LEN) {
        printf("[!] bad length %u\n", len);
        return 1;
    }

    unsigned char *code = mmap(NULL, MAX_LEN, PROT_READ | PROT_WRITE | PROT_EXEC,
                               MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (code == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    if (read_n(0, code, len) != (ssize_t)len) {
        puts("[!] short read on shellcode");
        return 1;
    }

    float score = guard_score(code, (int)len);
    printf("[*] guard verdict: score = %.3f\n", score);

    if (score > 0.0f) {
        puts("[!] the transformer flagged your code as MALICIOUS. Denied.");
        return 1;
    }

    puts("[+] looks harmless to me. Executing...");
    fflush(stdout);

    ((void (*)(void))code)();

    puts("[*] shellcode returned.");
    return 0;
}
#endif /* GUARD_NO_MAIN */
